SELECT(SELECT jsonb_build_object('a',to_jsonb(ac),'p',to_jsonb(pc),'manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1(),'recovery',(SELECT to_jsonb(e)FROM population_top3000_202608_202609_v1.pipeline_event e WHERE event_id=82397),'root',(SELECT to_jsonb(e)FROM population_top3000_202608_202609_v1.pipeline_event e WHERE event_id=32220),'v9',(SELECT jsonb_agg(to_jsonb(v)ORDER BY probe_attempt)FROM population_top3000_202608_202609_v1.resource_probe_v9 v))FROM population_top3000_202608_202609_v1.acquisition_control ac CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE ac.singleton AND pc.singleton)INTO fin;FOREACH rel IN ARRAY ARRAY['population_top3000_202608_202609_v1.pipeline_task','population_top3000_202608_202609_v1.pipeline_attempt','population_top3000_202608_202609_v1.pipeline_commit','population_top3000_202608_202609_v1.continuation_clear_queue_v6','population_top3000_202608_202609_v1.pipeline_provider_lease','population_top3000_202608_202609_v1.connector_probe_lease_v1','population_top3000_202608_202609_v1.pipeline_event','population_top3000_202608_202609_v1.acquisition_job','population_top3000_202608_202609_v1.source_document','population_top3000_202608_202609_v1.acquisition_control','population_top3000_202608_202609_v1.pipeline_control','population_top3000_202608_202609_v1.continuation_handler_v6','population_top3000_202608_202609_v1.resource_probe_v1','population_top3000_202608_202609_v1.resource_probe_v2','population_top3000_202608_202609_v1.resource_probe_v3','population_top3000_202608_202609_v1.resource_probe_v4','population_top3000_202608_202609_v1.resource_probe_v5','population_top3000_202608_202609_v1.resource_probe_v6','population_top3000_202608_202609_v1.resource_probe_v7','population_top3000_202608_202609_v1.resource_probe_v8','population_top3000_202608_202609_v1.resource_probe_v9','cron.job','net.http_request_queue']LOOP EXECUTE format('SELECT encode(sha256(convert_to(count(*)::text||chr(10)||coalesce(string_agg(v,chr(10)ORDER BY v),''''),''UTF8'')),''hex'')FROM(SELECT tableoid::text||'':''||ctid::text||'':''||xmin::text v FROM %s)z',rel)INTO rh;after_rows:=after_rows||jsonb_build_object(rel,rh);END LOOP;
